// Lead sent by another flow (email auto-reply, site form, WhatsApp) or by hand
const b = $('New lead (webhook)').first().json.body ?? {};
const found = $('Find customer').all().map(i => i.json).find(c => c && c.id);
const created = $('Create customer').isExecuted ? $('Create customer').first().json : null;
const c = found || created;
if (!b.message) throw new Error('Lead without message: send at least "email" and "message"');
return [{ json: { customer_id: c.id, name: c.name, email: c.email, company: c.company || b.company || '', phone: c.phone || b.phone || '', source: b.source || c.source || 'email', message: String(b.message).trim() } }];

// Leads registered directly in Supabase (status = lead) with the message in "notes"
return $input.all().map(i => i.json).filter(c => c.id && (c.notes || '').trim()).map(c => ({ json: {
  customer_id: c.id, name: c.name, email: c.email, company: c.company || '', phone: c.phone || '', source: c.source || 'other', message: c.notes.trim() } }));

// Builds the prompt with the lead + the service catalog from Supabase
const services = $('Get services').all().map(i => i.json).filter(s => s.code);
const catalog = services.sort((a,b) => a.sort_order - b.sort_order)
  .map(s => `- ${s.code} ${s.name} (${s.category}): ${s.description} Ideal para: ${s.ideal_for || '-'}. Inclui: ${(s.features || []).join(', ')}`).join('\n');
const label = { email: 'e-mail', website: 'formulário do site', whatsapp: 'WhatsApp', referral: 'indicação', other: 'outro' };
const src = $('Lead from webhook').isExecuted ? $('Lead from webhook') : $('Leads with message');
return src.all().map(i => { const l = i.json; return { json: { ...l, prompt: [
  '# CATÁLOGO DA VIDAL TECHNOLOGIES', catalog,
  'Fora do catálogo: aplicativos nativos para lojas, logo e identidade visual, gestão de redes sociais e tráfego pago, suporte de TI.',
  '', '# LEAD',
  `Canal: ${label[l.source] || l.source}`, `Nome: ${l.name || '(não informado)'}`, `Empresa: ${l.company || '(não informada)'}`,
  `E-mail: ${l.email || '(não informado)'}`, `Telefone: ${l.phone || '(não informado)'}`, '', 'Mensagem:', l.message ].join('\n') } }; });

// Reads Claude's JSON, maps it to the database enums and builds the email report
const leads = $('Build prompt').all().map(i => i.json);
const P = { 'Alta': 'high', 'Média': 'medium', 'Media': 'medium', 'Baixa': 'low' };
const F = { 'Alta': 'high', 'Média': 'medium', 'Media': 'medium', 'Baixa': 'low', 'Fora do catálogo': 'out_of_scope' };
const SRC = { email: 'E-mail', website: 'Formulário do site', whatsapp: 'WhatsApp', referral: 'Indicação', other: 'Outro' };
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ul = a => '<ul>' + (a || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ul>';
const ol = a => '<ol>' + (a || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ol>';
return $input.all().map((item, idx) => {
  const lead = leads[idx];
  const raw = (item.json.text || '').trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  let ev; try { ev = JSON.parse(raw); } catch (e) { throw new Error('Claude did not return valid JSON: ' + raw.slice(0, 300)); }
  const score = Math.max(0, Math.min(100, Math.round(Number(ev.score) || 0)));
  const color = { high: '#1f9d55', medium: '#FBC105', low: '#888888' }[P[ev.priority]] || '#888888';
  const html = `<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#111">
 <div style="background:#000;background-image:linear-gradient(#000,#000);padding:18px 24px"><img src="https://vidaltechnologies.com.br/catalogo/logo-email.png" alt="vidal technologies" height="28" style="display:block;height:28px"><div style="color:#FBC105;font-size:13px;letter-spacing:.08em;text-transform:uppercase;margin-top:8px">Avaliação de lead</div></div>
 <div style="padding:20px 24px;border:1px solid #eee;background:#fff">
  <p style="margin:0 0 6px"><b>${esc(lead.name || 'Lead sem nome')}</b> · ${esc(lead.company || 'empresa não informada')} · ${esc(SRC[lead.source] || lead.source)}</p>
  <p style="margin:0 0 16px;color:#555">${esc(lead.email)} ${esc(lead.phone)}</p>
  <p style="display:inline-block;background:${color};color:#000;padding:6px 12px;border-radius:999px;font-weight:bold">Prioridade ${esc(ev.priority)} · ${score}/100</p>
  <h3>1. Resumo do lead</h3><p>${esc(ev.summary)}</p>
  <h3>2. Necessidades e problemas</h3>${ul(ev.needs)}
  <h3>3. Aderência às soluções</h3><p><b>${esc(ev.fit)}</b> · ${esc((ev.recommended_services || []).join(', '))}<br>${esc(ev.fit_reason)}</p>
  <h3>4. Prioridade sugerida</h3><p><b>${esc(ev.priority)} (${score}/100)</b> · ${esc(ev.score_breakdown)}<br>${esc(ev.priority_justification)}</p>
  <h3>5. Informações que ainda faltam</h3>${ul(ev.missing_info)}
  <h3>6. Perguntas para a próxima conversa</h3>${ol(ev.next_questions)}
  <h3>7. Próximo passo recomendado</h3><p><b>${esc(ev.next_step)}</b></p>
  <hr style="border:none;border-top:1px solid #eee"><p style="color:#888;font-size:12px">Mensagem original:<br>${esc(lead.message).replace(/\n/g,'<br>')}</p>
 </div></div>`;
  return { json: { ...lead, ev, score, priority: P[ev.priority] || 'low', fit: F[ev.fit] || 'low',
    email_subject: `[Lead ${ev.priority} · ${score}] ${lead.name || lead.email || 'novo lead'}`, email_html: html } };
});
